#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    int q = (int)readInt();
    vector<int> lo(q), hi(q);
    int maximum = 0;
    for (int i = 0; i < q; i++) {
        lo[i] = (int)readInt();
        hi[i] = (int)readInt();
        maximum = max(maximum, hi[i]);
    }
    // pre[x]: how many of 1..x have no repeated digit.
    vector<int> pre(maximum + 1, 0);
    for (int x = 1; x <= maximum; x++) {
        int mask = 0, ok = 1;
        for (int y = x; y; y /= 10) {
            int bit = 1 << (y % 10);
            if (mask & bit) {
                ok = 0;
                break;
            }
            mask |= bit;
        }
        pre[x] = pre[x - 1] + ok;
    }
    string out;
    for (int i = 0; i < q; i++) {
        out += to_string(pre[hi[i]] - pre[lo[i] - 1]);
        out.push_back('\n');
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        int[] lo = new int[q], hi = new int[q];
        int maximum = 0;
        for (int i = 0; i < q; i++) {
            lo[i] = nextInt();
            hi[i] = nextInt();
            maximum = Math.max(maximum, hi[i]);
        }
        int[] pre = new int[maximum + 1];
        for (int x = 1; x <= maximum; x++) {
            int mask = 0, ok = 1;
            for (int y = x; y > 0; y /= 10) {
                int bit = 1 << (y % 10);
                if ((mask & bit) != 0) {
                    ok = 0;
                    break;
                }
                mask |= bit;
            }
            pre[x] = pre[x - 1] + ok;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) sb.append(pre[hi[i]] - pre[lo[i] - 1]).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := nextInt()
	lo := make([]int, q)
	hi := make([]int, q)
	maximum := 0
	for i := 0; i < q; i++ {
		lo[i], hi[i] = nextInt(), nextInt()
		maximum = max(maximum, hi[i])
	}
	pre := make([]int, maximum+1)
	for x := 1; x <= maximum; x++ {
		mask, ok := 0, 1
		for y := x; y > 0; y /= 10 {
			bit := 1 << (y % 10)
			if mask&bit != 0 {
				ok = 0
				break
			}
			mask |= bit
		}
		pre[x] = pre[x-1] + ok
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i := 0; i < q; i++ {
		out.WriteString(strconv.Itoa(pre[hi[i]] - pre[lo[i]-1]))
		out.WriteByte('\n')
	}
}
